<?php
declare(strict_types=1);
function seedMaterials(\EducacionalERP\Domain\Store $db):array
{
    $period=$db->insert('periodos_letivos',['codigo'=>'2027','descricao'=>'Ano de teste','data_inicio'=>'2027-01-01','data_fim'=>'2027-12-31']);$course=$db->insert('cursos',['codigo'=>'EF1','nome'=>'FUNDAMENTAL']);$shift=$db->insert('turnos',['codigo'=>'MANHA','nome'=>'MANHÃ']);$class=$db->insert('turmas',['codperiodo'=>$period,'idcurso'=>$course,'idturno'=>$shift,'codigo'=>'5A','nome'=>'5º ANO A','capacidade'=>1000]);
    $person=static fn(string $name,?string $cpf=null,int $active=1)=>$db->insert('pessoas',['nome'=>$name,'cpf'=>$cpf,'ativo'=>$active,'telefone'=>'011 98765-4321']);$father=$person('PAI TESTE','52998224725');$mother=$person('MÃE TESTE','11144477735');$other=$person('AVÓ TESTE');$closed=$person('RESPONSÁVEL ENCERRADO','01234567890');$inactive=$person('RESPONSÁVEL INATIVO','93541134780',0);
    $student=function(string $name,string $ra,bool $enroll=true,int $active=1,bool $deleted=false)use($db,$person,$period,$course,$class){$pid=$person($name);$id=$db->insert('alunos',['codpessoa'=>$pid,'ra'=>$ra,'ativo'=>$active]);if($enroll)$db->insert('matriculas',['idaluno'=>$id,'codperiodo'=>$period,'idcurso'=>$course,'idturma_atual'=>$class,'data_matricula'=>'2026-11-17','origem'=>'teste','excluido_em'=>$deleted?'2026-11-17 00:00:00':null]);return [$id,$pid];};
    [$ana,$anaPerson]=$student('ANA TESTE','000042');[$bruno]=$student('BRUNO TESTE','000057');[$pending]=$student('EVA SEM TURMA','000058',false);[$inactiveStudent]=$student('INATIVO TESTE','000059',true,0);[$deleted]=$student('EXCLUÍDO TESTE','000060',true,1,true);
    $link=static fn(int $student,int $responsible,array $extra=[])=>$db->insert('aluno_responsaveis',array_replace(['idaluno'=>$student,'codpessoa_responsavel'=>$responsible,'parentesco'=>'outro','inicio_vigencia'=>'2000-01-01 00:00:00'],$extra));$link($ana,$father,['responsavel_financeiro'=>1]);$link($ana,$father,['responsavel_academico'=>1]);$link($ana,$mother);$link($ana,$other);$link($ana,$closed,['fim_vigencia'=>'2001-01-01 00:00:00']);$link($ana,$inactive);$link($bruno,$other);
    $company=$db->insert('coligadas',['nome'=>'OUTRA ESCOLA','razao_social'=>'OUTRA ESCOLA']);$otherPeriod=$db->insert('periodos_letivos',['codcoligada'=>$company,'codigo'=>'2027','descricao'=>'Outra escola','data_inicio'=>'2027-01-01','data_fim'=>'2027-12-31']);
    return compact('period','course','shift','class','father','mother','other','closed','ana','anaPerson','bruno','pending','inactiveStudent','deleted','company','otherPeriod');
}
